normalized_output:
NUMBER n.
INPUT(n).
NUMBER left=1.
NUMBER right=n.
LOOP (left<=right) {
    NUMBER middle=(left+right)/2.
    NUMBER left2=middle.
    NUMBER right2=n.
    LOOP (left2<=right2) {
        NUMBER middle2=(left2+right2)/2.
        NUMBER left3=1.
        NUMBER right3=middle2.
        NUMBER result=0.
        LOOP (left3<=right3) {
            NUMBER middle3=(left3+right3)/2.
            IF (middle2%middle3==0) { result=middle3. }
            IF (middle2>=middle3) { left3=middle3+1. }
            ELSE { right3=middle3-1. }
        }
        IF (result!=0) { left2=middle2+1. }
        ELSE { right2=middle2-1. }
    }
    IF (result!=0) { left=middle+1. }
    ELSE { right=middle-1. }
}
DISPLAYNL(left).

